            handler.reset();
            datagram_ = &handler;
            datagramIn_.resize(static_cast<size_t>(bufSize > 0 ? bufSize : (64 << 10)));
            Result<> rc = serve(sqEntries, cqEntries, 0, sessionPoolSize, 0, bufSize, idleTimeoutSecs);
            reset();
            return rc;
        }

