            if (auto poolRes = sessionPool_.init(sessionSlots); !poolRes) [[unlikely]]
            {
                LOG_ERROR("Proactor::serve: initialising session pool ({} slots) failed", sessionSlots);
                reset();
                return std::unexpected(ERR::POOL_ALLOC_FAILED);
