            {
                const lua_Integer v = clampValue<lua_Integer>(num, static_cast<lua_Integer>(kMinMaxLogLength),
                                                              static_cast<lua_Integer>(kMaxMaxLogLength));
                if (v != num)
                    printError("logger.maxLogLength clamped");
