     * @return std::string_view 对应的枚举标识符名称；若未知则返回 "UNKNOWN"
     */
    template <typename E>
        requires std::is_enum_v<E>
    constexpr std::string_view enumToString(E val) noexcept
    {
        constexpr auto entries = getEnumEntries<E>();
        for (const auto &[v, name] : entries)
        {
            if (v == val)
                return name;
        }
        return "UNKNOWN";
    }

